\title{Balancing Ratios of Circular Partitions:\\
Windowing Monotonicity and Full-Period Balance}
\author{Aristotle}
\date{2026-07-11}

\begin{document}
\maketitle

\begin{abstract}
We study the balance of circular partitions generated by placing points on a
circle, where the arc lengths form a positive periodic sequence. For a window
length $r \ge 1$ we define the $r$-window ratio as the ratio of the largest to
the smallest sum of $r$ consecutive arcs, taken over all cyclic starting
positions. This finite-stage quantity, denoted $\mu^r$, generalizes the classical
single-gap ratio $\mu^1 = g_{\max}/g_{\min}$. We prove two structural pillars.
First, a \emph{windowing monotonicity} theorem: for every $r \ge 1$,
$1 \le \mu^r \le \mu^1$, so aggregating consecutive arcs never worsens balance.
Second, a \emph{full-period balance} theorem: whenever the window length is a
positive multiple $kn$ of the period $n$, every window has identical length $kL$
(where $L$ is the total circumference), so $\mu^{kn} = 1$ exactly. Together these
results show that the balancing ratio sequence oscillates and returns to perfect
balance infinitely often, explaining why the long-run balancing ratio must be
defined as a limit superior rather than a limit. We illustrate the theory with
the perfectly uniform partition (window ratio $1$ at every scale) and the
three-point van der Corput partition $\{1/4, 1/4, 1/2\}$, which realizes the
benchmark single-gap ratio $2$. These results form the structural scaffold for
the upper-bound conjecture $\mu_r \le 2r/p + 1$ for recipes of length $p$.
\end{abstract}

\section{Introduction}

A recurring theme in combinatorial geometry and the theory of uniform
distribution is the following: place a sequence of points on a circle so that, at
every stage, consecutive arcs are as equal as possible. Classical results in the
de Bruijn--Erd\H{o}s tradition of cake-cutting and in the theory of
low-discrepancy sequences quantify the unavoidable imbalance. In this paper we
isolate and prove two clean structural principles governing the \emph{balancing
ratio} of a periodic circular partition, and we assemble the framework in which
the sharp upper-bound conjecture is naturally stated.

The two principles are intuitive but, once made precise, surprisingly powerful:
(1) aggregation into windows of $r$ consecutive arcs is never less fair than
serving single arcs; (2) whenever the serving block is a whole number of full
loops around the circle, every block is exactly equal. The second principle
forces the balancing ratio sequence to oscillate and to touch its minimum value
$1$ infinitely often, so the meaningful long-run measure of imbalance is the
limit superior.

\section{Setting and definitions}

\begin{definition}[Circular partition]
A \emph{circular partition} consists of a positive integer $n \ge 1$ (the number
of distinct arcs) and a function $g : \mathbb{N} \to \mathbb{R}$ (the gap-length
sequence) with $g_i > 0$ for all $i$ and $g_{i+n} = g_i$ for all $i$. In
particular $g_i = g_{i \bmod n}$.
\end{definition}

\begin{definition}[Extremal single gaps]
The maximum and minimum gaps are
$g_{\max} = \max_{0 \le i < n} g_i$ and $g_{\min} = \min_{0 \le i < n} g_i$.
\end{definition}

\begin{definition}[Window sum]
For $r, i \in \mathbb{N}$ the \emph{$r$-window sum} is
$W_r(i) = \sum_{j=0}^{r-1} g_{i+j}$.
\end{definition}

\begin{definition}[Extremal window sums]
Over the $n$ cyclic starting positions,
$\mathrm{maxwin}(r) = \max_{0 \le i < n} W_r(i)$ and
$\mathrm{minwin}(r) = \min_{0 \le i < n} W_r(i)$.
\end{definition}

\begin{definition}[Balancing ratios]
The single-gap ratio and $r$-window ratio are
\[
\mu^1 = \frac{g_{\max}}{g_{\min}}, \qquad
\mu^r = \frac{\mathrm{maxwin}(r)}{\mathrm{minwin}(r)}.
\]
For a recipe of length $p$ generating a periodic partition, the long-run
balancing ratio is $\mu_r = \limsup_{n \to \infty} \mu^r_n$.
\end{definition}

\begin{definition}[Total circumference]
$L = \sum_{j=0}^{n-1} g_j$.
\end{definition}

Since $g_{\min}$ is a minimum of finitely many positive numbers, $g_{\min} > 0$,
hence $L > 0$ and $g_{\max} \ge g_{\min} > 0$.

\section{Elementary bounds}

\begin{lemma}[Nontriviality]
$g_{\min} \le g_{\max}$, hence $\mu^1 \ge 1$.
\end{lemma}
\begin{proof}
The minimum of a nonempty finite set is at most its maximum; dividing
$g_{\max} \ge g_{\min} > 0$ by $g_{\min}$ yields $\mu^1 \ge 1$.
\end{proof}

\begin{lemma}[Per-arc envelopes]
For every $i$, $g_{\min} \le g_i \le g_{\max}$.
\end{lemma}
\begin{proof}
Reduce the index modulo $n$ by periodicity, then apply the definitions of
$g_{\min}$ and $g_{\max}$ over $\{0, \dots, n-1\}$.
\end{proof}

\begin{lemma}[Window envelopes]
For every $r$ and $i$, $r \, g_{\min} \le W_r(i) \le r \, g_{\max}$, hence
$r \, g_{\min} \le \mathrm{minwin}(r)$ and $\mathrm{maxwin}(r) \le r \, g_{\max}$.
\end{lemma}
\begin{proof}
Sum the per-arc envelopes over the $r$ terms of the window, then take extrema
over starting positions.
\end{proof}

\begin{lemma}[Positivity of the minimum window]
If $r \ge 1$ then $\mathrm{minwin}(r) > 0$.
\end{lemma}
\begin{proof}
$\mathrm{minwin}(r) \ge r \, g_{\min} > 0$ since $r \ge 1$ and $g_{\min} > 0$.
\end{proof}

\section{Windowing monotonicity}

\begin{theorem}[Windowing improves balance]
For every window length $r \ge 1$, $\mu^r \le \mu^1$.
\end{theorem}
\begin{proof}
The denominator $\mathrm{minwin}(r)$ is positive, so the ratio is well defined.
Using the window envelopes, together with $g_{\max} \ge 0$ and
$r\,g_{\min} > 0$,
\[
\frac{\mathrm{maxwin}(r)}{\mathrm{minwin}(r)}
\le \frac{r \, g_{\max}}{\mathrm{minwin}(r)}
\le \frac{r \, g_{\max}}{r \, g_{\min}}
= \frac{g_{\max}}{g_{\min}}.
\]
The first inequality replaces the numerator with its upper envelope; the second
replaces the denominator with its lower envelope; the last equality cancels the
factor $r > 0$.
\end{proof}

\begin{theorem}[Lower bound]
For every $r \ge 1$, $\mu^r \ge 1$.
\end{theorem}
\begin{proof}
Since $\mathrm{minwin}(r) \le \mathrm{maxwin}(r)$ with positive denominator, the
quotient is at least $1$.
\end{proof}

Combining the two theorems gives $1 \le \mu^r \le \mu^1$ for all $r \ge 1$: the
single-gap ratio is the envelope of the entire window-ratio profile.

\section{Full-period balance}

\begin{lemma}[Phase invariance of full-period sums]
For every starting position $i$, $\sum_{j=0}^{n-1} g_{i+j} = L$.
\end{lemma}
\begin{proof}
Induct on $i$. For $i = 0$ the sum is $L$ by definition. For the step, we show
the full-period sum is unchanged when the start advances by one. Peeling the last
term from the sum over $\{0,\dots,n\}$ of $g_{k+j}$ gives
$\sum_{j=0}^{n} g_{k+j} = \sum_{j=0}^{n-1} g_{k+j} + g_{k+n}$, while peeling the
first term (reindexing $j \mapsto j+1$) gives
$\sum_{j=0}^{n} g_{k+j} = \sum_{j=0}^{n-1} g_{k+(j+1)} + g_{k}$. Equating and
using $g_{k+n} = g_k$, the boundary terms cancel, so
$\sum_{j=0}^{n-1} g_{k+(j+1)} = \sum_{j=0}^{n-1} g_{k+j}$. The inductive
hypothesis finishes the proof.
\end{proof}

\begin{lemma}[Multi-period sums]
For every $k \in \mathbb{N}$ and start $i$, $W_{kn}(i) = k \, L$.
\end{lemma}
\begin{proof}
Induct on $k$. The case $k = 0$ is the empty sum. For the step, split the range
$\{0, \dots, (m+1)n - 1\}$ into the first $mn$ indices (giving $mL$ by the
hypothesis) and the last $n$ indices (a full-period sum starting at $i + mn$,
equal to $L$). Adding yields $(m+1)L$.
\end{proof}

\begin{theorem}[Perfect balance at the period]
$\mu^{n} = 1$.
\end{theorem}
\begin{proof}
By phase invariance, $i \mapsto W_n(i)$ is constant equal to $L$, so
$\mathrm{maxwin}(n) = \mathrm{minwin}(n) = L$ and, since $L > 0$, the ratio is
$1$.
\end{proof}

\begin{theorem}[Perfect balance at every multiple of the period]
For every integer $k \ge 1$, $\mu^{kn} = 1$.
\end{theorem}
\begin{proof}
By the multi-period lemma, $i \mapsto W_{kn}(i)$ is constant equal to $kL$. Since
$k \ge 1$ and $L > 0$, $kL \ne 0$, so
$\mathrm{maxwin}(kn) = \mathrm{minwin}(kn) = kL$ and the ratio is $1$.
\end{proof}

\begin{corollary}[Oscillation and the limit superior]
The balancing ratio sequence $r \mapsto \mu^r$ returns to $1$ at every positive
multiple of the period. If the partition is non-uniform ($\mu^1 > 1$), the
sequence does not converge, and the appropriate long-run measure of imbalance is
$\mu_r = \limsup \mu^r_n$.
\end{corollary}

\section{Extremal examples}

\begin{example}[Uniform partition]
If all arcs have length $1/n$, then every window of length $r$ has sum $r/n$
regardless of start, so $\mu^r = 1$ for all $r \ge 1$. This is the unique
partition perfectly balanced at every scale.
\end{example}

\begin{example}[van der Corput three-point partition]
The first three base-2 van der Corput points give the period-$3$ pattern
$g = (\tfrac14, \tfrac14, \tfrac12, \dots)$, i.e.\ $g_i = \tfrac12$ if
$i \equiv 2 \pmod 3$ and $g_i = \tfrac14$ otherwise. Then $g_{\max} = \tfrac12$,
$g_{\min} = \tfrac14$, so $\mu^1 = 2$, the de Bruijn--Erd\H{o}s benchmark. By the
monotonicity theorem every $\mu^r \le 2$, and by full-period balance $\mu^{3k} =
1$ (each block of $3$ arcs has length $1$). The imbalance lives entirely in the
non-period-aligned windows.
\end{example}

\section{Algorithms}

The framework is computable for any explicit periodic gap sequence. To compute
$\mu^r$ at stage $n$, evaluate $W_r(i)$ for each of the $n$ cyclic starts and
divide the maximum by the minimum; a prefix-sum implementation runs in $O(n)$
after $O(n)$ preprocessing. Sweeping $r = 1, \dots, R$ produces the balancing
ratio profile, which visibly stays within $[1, \mu^1]$ and hits $1$ at every
multiple of the period.

\section{Applications}

The model abstracts recurring-event scheduling (even load across shifting time
windows), ring networks and sensor placement (uniform coverage of consecutive
sensors), low-discrepancy sampling (local uniformity of quasi-Monte Carlo
sequences), and fair division (bounding inequality of consecutive-slice servings
under a fixed recipe).

\section{Discussion and the upper-bound conjecture}

The perfect-balance recurrence pins $\mu^r = 1$ exactly whenever $r$ is a
multiple of the period $p$, so the conjectured envelope $\mu_r \le 2r/p + 1$ is
exact at the resets. Between resets, windowing monotonicity keeps the excursions
controlled by the single-gap ratio. The outstanding problem is to quantify the
surplus a window can accumulate while wrapping a non-integer number of periods,
reducing an asymptotic question to a finite per-period estimate.

\section{Future directions}

Building on windowing monotonicity ($\mu^r \le \mu^1$) and full-period balance
($\mu^{kp} = 1$): prove the recipe upper bound $\mu_r \le 2r/p + 1$; establish
sharpness of the window envelope (for every non-uniform partition some $r$ has
$1 < \mu^r < \mu^1$, with equality to $\mu^1$ only at $r = 1$); show the minimum
achievable $\limsup_r \mu_r$ over recipes of length $p$ decreases to $1$ at rate
$\Theta(1/p)$; and build a discrepancy bridge $\mu_r - 1 = \Theta(r \, D_n)$
along the stages realizing the limit superior.

\section{Conclusion}

We proved windowing monotonicity ($1 \le \mu^r \le \mu^1$) and full-period
balance ($\mu^{kn} = 1$) for periodic circular partitions. These reveal the
oscillatory nature of the balancing ratio sequence, justify the limit-superior
formulation, and assemble the framework for the upper-bound conjecture
$\mu_r \le 2r/p + 1$.

